 public static void DrawBackground(Graphics g,TaskbarAppearance a,Rectangle rect){if(a.Transparent||rect.Width<1||rect.Height<1||a.EffectiveBackgroundOpacity<=0)return;
  using(var image=new Bitmap(rect.Width,rect.Height,System.Drawing.Imaging.PixelFormat.Format32bppPArgb)){
   using(var paint=Graphics.FromImage(image)){paint.Clear(Color.Transparent);var ramp=a.BackgroundRamp;if(ramp!=null&&ramp.Enabled)ramp.Draw(paint,new Rectangle(0,0,rect.Width,rect.Height),1);else if(a.GradientBackground)UsageRamp.Between(a.Background,a.BackgroundGradientEnd??a.GradientEnd).Draw(paint,new Rectangle(0,0,rect.Width,rect.Height),1);else paint.Clear(TaskbarAppearance.ParseColor(a.Background));}
   using(var attributes=new System.Drawing.Imaging.ImageAttributes()){var matrix=new System.Drawing.Imaging.ColorMatrix();matrix.Matrix33=(float)a.EffectiveBackgroundOpacity;attributes.SetColorMatrix(matrix);g.DrawImage(image,rect,0,0,image.Width,image.Height,GraphicsUnit.Pixel,attributes);}
  }
 }
 public static Bitmap Surface(MonitorConfig cfg,SystemSample sample,TaskbarGeometry geometry,Size size){var bitmap=new Bitmap(Math.Max(1,size.Width),Math.Max(1,size.Height),System.Drawing.Imaging.PixelFormat.Format32bppPArgb);using(var g=Graphics.FromImage(bitmap)){g.Clear(Color.Transparent);DrawBackground(g,cfg.Appearance,new Rectangle(0,0,bitmap.Width,bitmap.Height));Draw(g,cfg,sample,geometry.RenderDpi,geometry);}return bitmap;}
 public static Bitmap Preview(MonitorConfig cfg,SystemSample sample,int maxHeight=48){var geometry=Geometry(cfg,1,maxHeight,sample);return Surface(cfg,sample,geometry,new Size(geometry.Size.Width,Math.Min(maxHeight,geometry.Size.Height)));}
}
